            | ResolvedExprKind::Block { .. }
            | ResolvedExprKind::VecConstructor { .. }
            | ResolvedExprKind::If { .. }
            | ResolvedExprKind::Call { .. }
            | ResolvedExprKind::LiteralFormat { .. }
