        root: exact.root,
        projections: vec![field.clone(), field],
    };
    assert!(!borrow_place_shape_is_admitted(
        &DeclarationId::new(crate::byte_ops::BYTES_AS_SLICE_ID),
        &deeper,
    ));
}

