    requires string_len("pre")==3
    ensures string_len("post")==4
{7}
@id("plain") fn plain()->i64 {8}
@id("app.main") fn main()->i64 {0}
"#,
    );
    let selected = program
        .functions
        .iter()
        .find(|function| function.id.as_str() == "selected")
