    let mut forged = closure.clone();
    let selected = forged
        .functions
        .iter_mut()
        .find(|f| f.id.as_str() == "selected")
        .unwrap();
    let hir::ResolvedExprKind::Block { statements, .. } = &mut selected.body.kind else {
