fn nonempty_loan_plan_clones_preserve_cold_graph_builder_accounting() {
    let root = std::env::temp_dir().join(format!(
        "spx-semantic-loan-cache-{}-{}",
        std::process::id(),
        SERIAL.fetch_add(1, Ordering::Relaxed)
    ));
